package br.radio.zapdmr;
import org.junit.Test;
import static org.junit.Assert.*;
public class CarVoxGateTest {
 private CarVoxGate ready(){CarVoxGate gate=new CarVoxGate(1,1200);for(long t=1000;t<=2000;t+=20)gate.frame(false,-65,.2,true,false,t);return gate;}
 @Test public void levelWithoutVadNeverStarts(){CarVoxGate g=ready();for(long t=2100;t<7000;t+=20)assertNotEquals(CarVoxGate.Result.START,g.frame(false,-25,.2,true,false,t));}
 @Test public void minimumSpeechAndSilenceHang(){CarVoxGate g=ready();assertNotEquals(CarVoxGate.Result.START,g.frame(true,-30,.2,true,false,2100));assertEquals(CarVoxGate.Result.START,g.frame(true,-30,.2,true,false,2360));assertEquals(CarVoxGate.Result.SPEAKING,g.frame(true,-30,.2,true,true,2400));assertNotEquals(CarVoxGate.Result.END,g.frame(false,-65,.2,true,true,3000));assertEquals(CarVoxGate.Result.END,g.frame(false,-65,.2,true,true,3620));}
 @Test public void shortBurstsResetAndRxRequiresFreshQuiet(){CarVoxGate g=ready();g.frame(true,-30,.2,true,false,2100);g.frame(false,-65,.2,true,false,2200);assertNotEquals(CarVoxGate.Result.START,g.frame(true,-30,.2,true,false,2280));assertEquals(CarVoxGate.Result.RX_BLOCKED,g.frame(true,-20,.2,false,false,2300));assertNotEquals(CarVoxGate.Result.START,g.frame(true,-30,.2,true,false,3800));for(long t=4000;t<=4900;t+=20)g.frame(false,-65,.2,true,false,t);g.frame(true,-30,.2,true,false,5000);assertEquals(CarVoxGate.Result.START,g.frame(true,-30,.2,true,false,5260));}
 @Test public void constantSignalLocksOutAndTotHasCeiling(){CarVoxGate g=ready();g.frame(true,-30,.2,true,true,3000);CarVoxGate.Result result=null;for(long t=3020;t<10000;t+=20){result=g.frame(true,-30,.2,true,true,t);if(result==CarVoxGate.Result.UNSAFE)break;}assertEquals(CarVoxGate.Result.UNSAFE,result);assertTrue(g.reason().contains("constante"));g=ready();g.frame(true,-30,.2,true,true,3000);assertEquals(CarVoxGate.Result.UNSAFE,g.frame(true,-31,.3,true,true,183001));assertTrue(g.reason().contains("180"));}
 @Test public void tooLoudInputSuspendsBeforeTx(){CarVoxGate g=ready();g.frame(true,-10,.2,true,false,3000);assertEquals(CarVoxGate.Result.UNSAFE,g.frame(true,-10,.2,true,false,5020));}
 @Test public void staleCleanupCannotDisarmNextSession(){CarModeState.mode(true);CarModeState.armVox(1000);long previous=CarModeState.voxGeneration;CarModeState.disarmVox();CarModeState.armVox(2000);assertFalse(CarModeState.disarmVox(previous));assertTrue(CarModeState.voxArmed);assertTrue(CarModeState.disarmVox(CarModeState.voxGeneration));CarModeState.mode(false);}
 @Test public void stateLeaseAndTargetChangeDisarm(){CarModeState.mode(true);assertFalse(CarModeState.voxArmed);CarModeState.armVox(1000);assertTrue(CarModeState.voxArmed);assertTrue(CarModeState.voxLeaseValid(2800));assertFalse(CarModeState.voxLeaseValid(2801));CarModeState.invalidate();assertFalse(CarModeState.voxArmed);CarModeState.armVox(3000);CarModeState.mode(false);assertFalse(CarModeState.voxArmed);}
}
